    if y > z { let t = y; y = z; z = t; }
    if x > y { let t = x; x = y; y = t; }

    // For sorted sides, the only potentially failing strict inequality is x + y > z.
    // If it fails, we need to increase (some sides) so that x + y becomes z+1 at least.
    // Minimum ops = max(0, (z + 1) - (x + y)).
